 change['missing_changes'].append(dict(session='18',record_type='missing',id=id,reason='2026-09-09；卷二216—239连续新证补充时效与收录边界，旧判断保留并限定历史阶段。',before=b,after=copy.deepcopy(x)));change['expanded_missing_ids'].append(id)








